import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../../components/AppLink";
import ExtractiveServiceSummary, {
  type ExtractiveServiceSummaryContent,
} from "../../components/ExtractiveServiceSummary";
import CaseStudyProofGrid, {
  type CaseStudyProofItem,
  type CaseStudyProofLabels,
} from "../../components/CaseStudyProofGrid";
import ClaimEvidencePanel from "../../components/ClaimEvidencePanel";
import EntityTrustPanel from "../../components/EntityTrustPanel";
import LandingVisualPanel from "../../components/LandingVisualPanel";
import Layout from "../../components/Layout";
import data from "../../data/data.json";
import type { Company } from "../../interfaces";
import images from "../../images";
import { useEffect } from "react";
import SEO from "../../components/seo";
import I18nHeadProvider from "../../components/I18nHeadProvider";
import ProofHighlights from "../../components/ProofHighlights";
import {
  buildBreadcrumbListSchema,
  buildFAQPageSchema,
  localizeSitePath,
} from "../../utils/structuredData";
import { trackCtaClick } from "../../utils/analytics";
import { getCaseStudyProofSource } from "../../utils/caseStudyProof";
import { buildContactIntentPath } from "../../utils/cta";

const info: Company = data[0];

type Chip = { chip: string };
type Card = { title: string; text: string };
type ListItem = { item: string };
type Step = { title: string; text: string };
type Faq = { q: string; a: string };
type ProfilePoint = { item: string };
type ProofItem = { eyebrow?: string; title: string; text: string; href?: string; ctaLabel?: string };

const SeoServicePage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const heroChips = t("services.seo.hero.chips", {
    returnObjects: true,
  }) as Chip[];

  const outcomes = t("services.seo.sections.outcomes.items", {
    returnObjects: true,
  }) as Card[];

  const idealFor = t("services.seo.sections.idealFor.items", {
    returnObjects: true,
  }) as ListItem[];

  const deliverables = t("services.seo.sections.deliverables.items", {
    returnObjects: true,
  }) as ListItem[];
  const extractive = t("services.seo.sections.extractive", {
    returnObjects: true,
  }) as ExtractiveServiceSummaryContent;
  const relatedResources = t("services.seo.sections.relatedResources", {
    returnObjects: true,
  }) as {
    title: string;
    subtitle?: string;
    items: ProofItem[];
  };

  const steps = t("services.seo.sections.process.steps", {
    returnObjects: true,
  }) as Step[];

  const faq = t("services.seo.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];
  const profilePoints = t("about.profile.points", {
    returnObjects: true,
  }) as ProfilePoint[];
  const proofLabels = t("proofBlocks.labels", {
    returnObjects: true,
  }) as CaseStudyProofLabels;
  const proofCtaLabel = t("proofBlocks.ctaLabel") as string;
  const reefCleaningProof = getCaseStudyProofSource(t, "reef-cleaning-company");
  const proofItems: CaseStudyProofItem[] = [
    {
      client: reefCleaningProof.client,
      businessType: reefCleaningProof.businessType,
      problem:
        reefCleaningProof.challenges[1] || reefCleaningProof.challenges[0] || "",
      intervention:
        reefCleaningProof.interventions[1] ||
        reefCleaningProof.interventions[0] ||
        "",
      result:
        reefCleaningProof.metrics[2]?.value ||
        reefCleaningProof.results[0] ||
        "",
      href: reefCleaningProof.href,
      ctaLabel: proofCtaLabel,
    },
  ].filter(
    (item) =>
      item.client &&
      item.businessType &&
      item.problem &&
      item.intervention &&
      item.result
  );

  const whatsappHref = info.whatsapp;

  return (
    <Layout data={info}>
      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-4xl">
              {t("services.seo.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("services.seo.hero.subtitle")}
            </p>

            {/* CTAs */}
            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to={buildContactIntentPath("quote")}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "seo_hero_primary",
                    cta_location: "seo_hero",
                    destination: buildContactIntentPath("quote"),
                    destination_type: "internal",
                  });
                }}
              >
                {t("services.seo.hero.primaryCta")}
              </Link>

              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "seo_hero_secondary",
                    cta_location: "seo_hero",
                    destination: whatsappHref,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("services.seo.hero.secondaryCta")}
              </a>
            </div>

            {/* Proof chips */}
            {Array.isArray(heroChips) && heroChips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {heroChips.map((c, idx) => (
                  <span
                    key={`${c.chip}-${idx}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {c.chip}
                  </span>
                ))}
              </div>
            ) : null}

            {/* Micro-proof line */}
            <p className="mx-auto mt-6 text-sm text-light/70 max-w-3xl">
              {t("services.seo.hero.microProof")}
            </p>
          </div>
        </div>
      </section>

      <ExtractiveServiceSummary content={extractive} />
      <ClaimEvidencePanel snippetKey="claims.services.seo" />

      <LandingVisualPanel
        imageSrc={images.bg_carousel_2.src}
        imageAlt={t("services.seo.landingVisual.imageAlt") as string}
        eyebrow={t("services.seo.landingVisual.eyebrow") as string}
        title={t("services.seo.landingVisual.title") as string}
        caption={t("services.seo.landingVisual.caption") as string}
      />

      <div className={styles.container}>
        <EntityTrustPanel
          eyebrow={t("about.profile.eyebrow") as string}
          name={info.founder?.name || info.companyName}
          role={t("about.profile.role") as string}
          summary={t("about.profile.summary") as string}
          highlights={Array.isArray(profilePoints) ? profilePoints.map((point) => point.item) : []}
          primaryHref="/about/"
          primaryLabel={t("menu.about") as string}
          secondaryHref="/portfolio/"
          secondaryLabel={t("menu.portfolio") as string}
        />
      </div>

      <CaseStudyProofGrid
        title={t("services.sharedProof.title") as string}
        subtitle={t("services.sharedProof.subtitle") as string}
        labels={proofLabels}
        items={proofItems}
      />

      {/* OUTCOMES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.seo.sections.outcomes.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(outcomes)
              ? outcomes.map((o, idx) => (
                  <div key={`${o.title}-${idx}`} className={styles.card}>
                    <h3 className="text-base sm:text-lg font-semibold text-light/90">
                      {o.title}
                    </h3>
                    <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                      {o.text}
                    </p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* IDEAL FOR */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.seo.sections.idealFor.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {Array.isArray(idealFor)
                ? idealFor.map((x, idx) => (
                    <li key={`${x.item}-${idx}`} className={styles.card}>
                      <p className="text-sm sm:text-base text-light/80">
                        {x.item}
                      </p>
                    </li>
                  ))
                : null}
            </ul>
          </div>
        </div>
      </section>

      {/* DELIVERABLES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.seo.sections.deliverables.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <div className={styles.card}>
              <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {Array.isArray(deliverables)
                  ? deliverables.map((d, idx) => (
                      <li key={`${d.item}-${idx}`}>{d.item}</li>
                    ))
                  : null}
              </ul>
            </div>

            {/* Helpful internal links */}
            <div className="mt-4 text-center text-sm text-light/70">
              <span className="mr-2">
                {t("services.seo.sections.deliverables.relatedLabel")}
              </span>
              <Link to="/services/web-design-development/" className="underline">
                {t("menu.services.webDesignDevelopment.nav")}
              </Link>
              <span className="mx-2">·</span>
              <Link to="/services/analytics/" className="underline">
                {t("menu.services.analytics.nav")}
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* PROCESS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.seo.sections.process.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(steps)
              ? steps.map((s, idx) => (
                  <div key={`${s.title}-${idx}`} className={styles.card}>
                    <div className="flex items-center gap-3">
                      <span className="inline-flex h-7 w-7 items-center justify-center rounded-full border border-black/10 bg-white text-sm font-semibold text-black/70">
                        {idx + 1}
                      </span>
                      <h3 className="text-base sm:text-lg font-semibold text-light/90">
                        {s.title}
                      </h3>
                    </div>
                    <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                      {s.text}
                    </p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.seo.sections.faq.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl space-y-3">
            {Array.isArray(faq)
              ? faq.map((x, idx) => (
                  <details key={`${x.q}-${idx}`} className={styles.card}>
                    <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                      {x.q}
                    </summary>
                    <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                      {x.a}
                    </p>
                  </details>
                ))
              : null}
          </div>
        </div>
      </section>

      <ProofHighlights
        title={relatedResources?.title}
        subtitle={relatedResources?.subtitle}
        items={Array.isArray(relatedResources?.items) ? relatedResources.items : []}
      />

      {/* FINAL CTA */}
      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("services.seo.sections.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("services.seo.sections.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to={buildContactIntentPath("quote")}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "seo_final_primary",
                    cta_location: "seo_final_cta",
                    destination: buildContactIntentPath("quote"),
                    destination_type: "internal",
                  });
                }}
              >
                {t("services.seo.sections.finalCta.primaryCta")}
              </Link>

              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "seo_final_secondary",
                    cta_location: "seo_final_cta",
                    destination: whatsappHref,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("services.seo.sections.finalCta.secondaryCta")}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

const SeoServiceHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const faq = t("services.seo.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];
  const faqSchema = buildFAQPageSchema(faq);
  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.servicesHub.nav") as string,
      path: localizeSitePath("/services/", language, defaultLanguage),
    },
    {
      name: t("menu.services.seo.nav") as string,
      path: localizeSitePath("/services/seo/", language, defaultLanguage),
    },
  ]);
  const additionalSchemas = [breadcrumbSchema, faqSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={info}
      titleKey="services.seo.metaTitle"
      descriptionKey="services.seo.metaDescription"
      pathname="/services/seo/"
      schemaType="ProfessionalService"
      pageSchemaType="Service"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <SeoServiceHeadContent />
  </I18nHeadProvider>
);

export default SeoServicePage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;


const styles = {
    sectionWrapper: "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
    labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
    container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
    card :"rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
    cardTitle: "text-base sm:text-lg font-semibold text-light/90",
    cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
